-- 8. REVISE checkout_shop_transaction RPC: SERVER-SIDE PRICE & TOTAL VERIFICATION
CREATE OR REPLACE FUNCTION public.checkout_shop_transaction(payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_transaction_id uuid;
    v_student_id text;
    v_total_amount numeric(10,2);
    v_calculated_total numeric(10,2) := 0;
    v_payment_method text;
    v_cashier_note text;
    v_items jsonb;
    v_item jsonb;
    v_product_id uuid;
    v_qty integer;
    v_current_stock integer;
    v_db_price numeric(10,2);
    v_db_name text;
    v_item_subtotal numeric(10,2);
    v_wallet_balance numeric(10,2);
    v_is_active boolean;
    v_daily_limit numeric(10,2);
    v_today_spent numeric(10,2);
BEGIN
    IF payload->>'id' IS NOT NULL THEN
        v_transaction_id := (payload->>'id')::uuid;
        IF EXISTS (SELECT 1 FROM public.shop_transactions WHERE id = v_transaction_id) THEN
            RETURN jsonb_build_object('success', true, 'transaction_id', v_transaction_id, 'duplicate', true);
        END IF;
    ELSE
        v_transaction_id := gen_random_uuid();
    END IF;

    v_student_id := payload->>'student_id';
    v_total_amount := (payload->>'total_amount')::numeric;
    v_payment_method := payload->>'payment_method';
    v_cashier_note := payload->>'cashier_note';
    v_items := payload->'items';

    IF v_items IS NULL OR jsonb_array_length(v_items) = 0 THEN
        RAISE EXCEPTION 'CART_EMPTY';
    END IF;

    -- Verify all items and recalculate true total from DB products table
    FOR v_item IN SELECT * FROM jsonb_array_elements(v_items)
    LOOP
        v_product_id := (v_item->'product'->>'id')::uuid;
        v_qty := (v_item->>'quantity')::integer;

        IF v_qty IS NULL OR v_qty <= 0 THEN
            RAISE EXCEPTION 'INVALID_QUANTITY';
        END IF;

        SELECT stock_qty, price, name INTO v_current_stock, v_db_price, v_db_name
        FROM public.products
        WHERE id = v_product_id
        FOR UPDATE;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'PRODUCT_NOT_FOUND';
        END IF;

        IF v_current_stock < v_qty THEN
            RAISE EXCEPTION 'INSUFFICIENT_STOCK';
        END IF;

        v_item_subtotal := v_db_price * v_qty;
        v_calculated_total := v_calculated_total + v_item_subtotal;
    END LOOP;

    -- Enforce total amount match
    IF v_total_amount IS NULL OR v_total_amount <> v_calculated_total OR v_total_amount <= 0 THEN
        RAISE EXCEPTION 'TOTAL_AMOUNT_MISMATCH: expected %, received %', v_calculated_total, v_total_amount;
    END IF;

    -- If Wallet payment, check balance AND daily limit
    IF v_payment_method = 'wallet' THEN
        IF v_student_id IS NULL THEN
            RAISE EXCEPTION 'STUDENT_ID_REQUIRED_FOR_WALLET';
        END IF;

        SELECT balance, is_active, daily_limit 
        INTO v_wallet_balance, v_is_active, v_daily_limit
        FROM public.wallet_accounts
        WHERE student_id = v_student_id
        FOR UPDATE;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'WALLET_NOT_FOUND';
        END IF;

        IF NOT v_is_active THEN
            RAISE EXCEPTION 'WALLET_INACTIVE';
        END IF;

        IF v_wallet_balance < v_total_amount THEN
            RAISE EXCEPTION 'INSUFFICIENT_WALLET';
        END IF;

        IF v_daily_limit IS NOT NULL THEN
            SELECT COALESCE(total_spent, 0) INTO v_today_spent
            FROM public.daily_spend_tracking
            WHERE student_id = v_student_id AND spend_date = current_date;

            IF NOT FOUND THEN
                v_today_spent := 0;
            END IF;

            IF (v_today_spent + v_total_amount) > v_daily_limit THEN
                RAISE EXCEPTION 'DAILY_LIMIT_EXCEEDED';
            END IF;
        END IF;
    END IF;

    -- Deduct Stock and prepare transaction
    FOR v_item IN SELECT * FROM jsonb_array_elements(v_items)
    LOOP
        v_product_id := (v_item->'product'->>'id')::uuid;
        v_qty := (v_item->>'quantity')::integer;

        UPDATE public.products
        SET stock_qty = stock_qty - v_qty,
            updated_at = now()
        WHERE id = v_product_id;
    END LOOP;

    -- Insert Shop Transaction
    INSERT INTO public.shop_transactions (id, student_id, items, total_amount, payment_method, cashier_note)
    VALUES (v_transaction_id, v_student_id, v_items, v_total_amount, v_payment_method, v_cashier_note);

    -- Insert Transaction Items with server-verified prices
    FOR v_item IN SELECT * FROM jsonb_array_elements(v_items)
    LOOP
        v_product_id := (v_item->'product'->>'id')::uuid;
        v_qty := (v_item->>'quantity')::integer;

        SELECT price, name INTO v_db_price, v_db_name
        FROM public.products WHERE id = v_product_id;

        INSERT INTO public.shop_transaction_items (transaction_id, product_id, product_name, unit_price, quantity, subtotal)
        VALUES (
            v_transaction_id,
            v_product_id,
            v_db_name,
            v_db_price,
            v_qty,
            v_db_price * v_qty
        );
    END LOOP;

    -- Deduct Wallet if wallet payment
    IF v_payment_method = 'wallet' THEN
        UPDATE public.wallet_accounts
        SET balance = balance - v_total_amount,
            updated_at = now()
        WHERE student_id = v_student_id;

        UPDATE public.students
        SET wallet_balance = wallet_balance - v_total_amount,
            updated_at = now()
        WHERE id = v_student_id;
        
        INSERT INTO public.wallet_transactions (
            student_id, type, amount,
            balance_before, balance_after,
            channel, cashier_note
        ) VALUES (
            v_student_id, 'purchase', v_total_amount,
            v_wallet_balance, v_wallet_balance - v_total_amount,
            'system', 'Shop Checkout Transaction: ' || v_transaction_id::text
        );

        INSERT INTO public.daily_spend_tracking (student_id, spend_date, total_spent)
        VALUES (v_student_id, current_date, v_total_amount)
        ON CONFLICT (student_id, spend_date)
        DO UPDATE SET total_spent = public.daily_spend_tracking.total_spent + v_total_amount;
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'transaction_id', v_transaction_id
    );
END;
$function$;

-- 9. REVISE process_tuition_payment RPC: SERVER-SIDE SUM & UNPAID VERIFICATION
CREATE OR REPLACE FUNCTION public.process_tuition_payment(payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_payment_id uuid;
    v_student_id text;
    v_fee_item_ids uuid[];
    v_total_amount numeric(10,2);
    v_calculated_total numeric(10,2) := 0;
    v_payment_method text;
    v_year text;
    v_receipt_number text;
    v_unpaid_count integer;
    v_expected_count integer;
BEGIN
    v_student_id := payload->>'student_id';
    SELECT ARRAY(SELECT jsonb_array_elements_text(payload->'fee_item_ids')::uuid) INTO v_fee_item_ids;
    v_expected_count := array_length(v_fee_item_ids, 1);
    
    IF v_expected_count IS NULL OR v_expected_count = 0 THEN
        RAISE EXCEPTION 'EMPTY_FEE_ITEMS';
    END IF;

    -- Lock and verify that all items belong to student, are unpaid, and calculate exact total
    PERFORM 1
    FROM public.fee_items
    WHERE id = ANY(v_fee_item_ids) AND student_id = v_student_id AND status = 'unpaid'
    FOR UPDATE;

    SELECT count(*), COALESCE(SUM(amount), 0)
    INTO v_unpaid_count, v_calculated_total
    FROM public.fee_items
    WHERE id = ANY(v_fee_item_ids) AND student_id = v_student_id AND status = 'unpaid';

    IF v_unpaid_count <> v_expected_count THEN
        RAISE EXCEPTION 'FEES_ALREADY_PAID_OR_INVALID';
    END IF;

    v_total_amount := (payload->>'total_amount')::numeric;

    -- Validate total amount matches database sum
    IF v_total_amount IS NULL OR v_total_amount <> v_calculated_total OR v_total_amount <= 0 THEN
        RAISE EXCEPTION 'TOTAL_AMOUNT_MISMATCH: expected %, received %', v_calculated_total, v_total_amount;
    END IF;

    v_payment_method := payload->>'payment_method';
    v_year := payload->>'academic_year';

    -- Generate Receipt Number atomically
    v_receipt_number := public.get_next_receipt_number(v_year);

    -- Insert Tuition Payment
    INSERT INTO public.tuition_payments (
        student_id, 
        fee_item_ids, 
        total_amount, 
        payment_method, 
        receipt_number
    )
    VALUES (
        v_student_id, 
        v_fee_item_ids, 
        v_total_amount, 
        v_payment_method, 
        v_receipt_number
    )
    RETURNING id INTO v_payment_id;

    -- Mark fee items as paid
    UPDATE public.fee_items
    SET status = 'paid', updated_at = now()
    WHERE id = ANY(v_fee_item_ids);

    RETURN jsonb_build_object(
        'success', true, 
        'payment_id', v_payment_id,
        'receipt_number', v_receipt_number
    );
END;
$function$;

-- 10. REVISE topup_wallet RPC: MAX LIMIT & IDEMPOTENCY
CREATE OR REPLACE FUNCTION public.topup_wallet(payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_student_id    text;
    v_amount        numeric(10,2);
    v_channel       text;
    v_cashier_note  text;
    v_svportal_ref  text;
    v_balance_before numeric(10,2);
    v_balance_after  numeric(10,2);
    v_transaction_id uuid;
    v_is_active     boolean;
BEGIN
    v_student_id   := payload->>'student_id';
    v_amount       := (payload->>'amount')::numeric;
    v_channel      := payload->>'channel';
    v_cashier_note := payload->>'cashier_note';
    v_svportal_ref := payload->>'svportal_ref';

    IF v_amount IS NULL OR v_amount <= 0 THEN
        RAISE EXCEPTION 'INVALID_AMOUNT';
    END IF;

    -- Max limit check per top-up transaction
    IF v_amount > 10000 THEN
        RAISE EXCEPTION 'AMOUNT_EXCEEDS_MAX_LIMIT';
    END IF;

    -- Validate channel
    IF v_channel IS NULL OR v_channel NOT IN ('counter', 'svportal', 'system', 'cash', 'qr', 'transfer') THEN
        v_channel := 'counter';
    END IF;

    -- Idempotency check if svportal_ref is provided
    IF v_svportal_ref IS NOT NULL THEN
        SELECT id, balance_before, balance_after INTO v_transaction_id, v_balance_before, v_balance_after
        FROM public.wallet_transactions
        WHERE svportal_ref = v_svportal_ref
        LIMIT 1;

        IF FOUND THEN
            RETURN jsonb_build_object(
                'success', true,
                'transaction_id', v_transaction_id,
                'balance_before', v_balance_before,
                'balance_after', v_balance_after,
                'duplicate', true
            );
        END IF;
    END IF;

    INSERT INTO public.wallet_accounts (student_id, balance, is_active)
    VALUES (v_student_id, 0, true)
    ON CONFLICT (student_id) DO NOTHING;

    SELECT balance, is_active INTO v_balance_before, v_is_active
    FROM public.wallet_accounts
    WHERE student_id = v_student_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'WALLET_NOT_FOUND';
    END IF;

    IF NOT v_is_active THEN
        RAISE EXCEPTION 'WALLET_INACTIVE';
    END IF;

    v_balance_after := v_balance_before + v_amount;

    UPDATE public.wallet_accounts
    SET balance = v_balance_after,
        updated_at = now()
    WHERE student_id = v_student_id;

    UPDATE public.students
    SET wallet_balance = v_balance_after,
        updated_at = now()
    WHERE id = v_student_id;

    INSERT INTO public.wallet_transactions (
        student_id, type, amount,
        balance_before, balance_after,
        channel, svportal_ref, cashier_note
    ) VALUES (
        v_student_id, 'topup', v_amount,
        v_balance_before, v_balance_after,
        v_channel, v_svportal_ref, v_cashier_note
    ) RETURNING id INTO v_transaction_id;

    RETURN jsonb_build_object(
        'success', true,
        'transaction_id', v_transaction_id,
        'balance_before', v_balance_before,
        'balance_after', v_balance_after
    );
END;
$function$;
